  `KmTotal` int DEFAULT NULL,
  `Pendencia_Id` int DEFAULT NULL,
  `AtivoCarro` enum('True','False') NOT NULL DEFAULT 'True',
  PRIMARY KEY (`Id`),
  KEY `FK_Carro_Filial` (`Filial_Id`),
  KEY `FK_Carro_Modelo` (`Modelo_Id`),
  KEY `FK_Carro_Pendencia` (`Pendencia_Id`),
