--
-- Table structure for table `reserva`
--

DROP TABLE IF EXISTS `reserva`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `reserva` (
  `Id` int NOT NULL AUTO_INCREMENT,
  `Pessoa_Id` int DEFAULT NULL,
  `PacoteDesconto_Id` int DEFAULT NULL,
  `Carro_Id` int DEFAULT NULL,
  `DataRetirada` datetime DEFAULT NULL,
  `DataDevolucao` datetime DEFAULT NULL,
  `ValorTotal` decimal(16,4) DEFAULT NULL,
  `StatusReserva` enum('Aberto','Pendente','Finalizado') DEFAULT NULL,
  `DataReserva` datetime DEFAULT NULL,
  `AtivoReserva` enum('True','False') NOT NULL DEFAULT 'True',
  PRIMARY KEY (`Id`),
  KEY `FK_Reserva_Pessoa` (`Pessoa_Id`),
  KEY `FK_Reserva_PacoteDesconto` (`PacoteDesconto_Id`),
  KEY `FK_Reserva_Carro` (`Carro_Id`),
  CONSTRAINT `FK_Reserva_Carro` FOREIGN KEY (`Carro_Id`) REFERENCES `carro` (`Id`),
  CONSTRAINT `FK_Reserva_PacoteDesconto` FOREIGN KEY (`PacoteDesconto_Id`) REFERENCES `pacotedesconto` (`Id`),
